function validate([n, queries]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 10^5.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  for (const query of queries) {
    if (query.length !== 2) return 'Each query is a pair [index, color].';
    const [index, color] = query;
    if (!Number.isInteger(index) || index < 0 || index > n - 1) return 'Each index is between 0 and n - 1.';
    if (!Number.isInteger(color) || color < 1 || color > 100000) return 'Each color is between 1 and 10^5.';
  }
  return null;
}

