function colorTheArray(n, queries) {
  const colors = new Array(n).fill(0);
  const answer = [];
  let count = 0;

  for (const [index, color] of queries) {
    const old = colors[index];
    if (old !== 0 && index > 0 && colors[index - 1] === old) {
      count--;
    }
    if (old !== 0 && index < n - 1 && colors[index + 1] === old) {
      count--;
    }
    colors[index] = color;
    if (index > 0 && colors[index - 1] === color) {
      count++;
    }
    if (index < n - 1 && colors[index + 1] === color) {
      count++;
    }
    answer.push(count);
  }
  return answer;
}

