function colorTheArray(n, queries) {
  const cells = Array(n).fill(0);
  return queries.map(([at, paint]) => {
    cells[at] = paint;
    let same = 0;
    for (let j = 0; j + 1 < n; j++) if (cells[j] !== 0 && cells[j] === cells[j + 1]) same++;
    return same;
  });
}

