function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const mode = int(0, 2);
    const q = 2000;
    let n, pick, palette;
    if (mode === 0) { n = 2000; pick = () => int(0, n - 1); palette = 3; }
    else if (mode === 1) { n = int(1, 20); pick = () => int(0, n - 1); palette = 2; }
    else { n = 100000; const base = int(0, n - 300); pick = () => base + int(0, 299); palette = 4; }
    const queries = Array.from({ length: q }, () => [pick(), rand() < 0.05 ? int(1, 100000) : int(1, palette)]);
    return [n, queries];
  }
  const n = int(1, 8);
  const q = int(1, 10);
